// Block 12: tolerant parse of the drafting model's completion into an output-block list.
// Un-parseable / non-array output is wrapped as a single text block so it renders as prose
// (the full-unify format-reliability mitigation). Never throws.
const mr = $('Call Invoke Model').first().json;
const raw = (mr.completion || '').toString();
function tryParse(s){ try { const v = JSON.parse(s); return Array.isArray(v) ? v : null; } catch(e){ return null; } }
let s = raw.trim();
const fence = s.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
if (fence) s = fence[1].trim();
let blocks = tryParse(s);
if (!blocks) {
  const i = s.indexOf('['); const j = s.lastIndexOf(']');
  if (i !== -1 && j !== -1 && j > i) blocks = tryParse(s.slice(i, j + 1));
}
if (!blocks || !blocks.length) { blocks = [{ type: 'text', md: raw }]; }
return [{ json: { output_blocks_json: JSON.stringify(blocks), completion: raw } }];

// SOLE TERMINAL of the success path (sub-workflow return determinism). Reads everything via
// absolute refs so the incoming item (Has Warnings? false / Alert Resolver Warnings /
// Alert Cost Sync Failed) doesn't matter. Carries the resolver's delta + manifest to Stage C (Block 12).
const wc = $('When Called').first().json;
const mr = $('Call Invoke Model').first().json;
const rs = $('Call Image Resolver').first().json;
return [{ json: {
  completion: mr.completion || '',
  rendered_delta: rs.rendered_delta || [],
  image_manifest: rs.image_manifest || [],
  image_models: rs.image_models || [],
  total_image_cost_pln: rs.total_image_cost_pln || 0,
  model: mr.model || '',
  cost_pln: mr.cost_pln,
  clickup_task_id: wc.clickup_task_id,
  reviewer_user_id: wc.reviewer_user_id,
  triggering_comment_id: wc.triggering_comment_id || '',
  web_sources: wc.web_sources || '[]'
} }];
